+      color: var(--muted);
+    }
+
+    form {
+      display: grid;
+      gap: 1.25rem;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 0.65rem;
+      padding: 1rem;
+      background: #f8faff;
+      border: 1px solid #dbe4f3;
+      border-radius: 1rem;
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 0.8rem;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin-top: 0.15rem;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      margin: 0;
+      font-size: 0.92rem;
+      line-height: 1.5;
+      color: var(--muted);
+    }
+
+    .button-row {
+      display: flex;
+      align-items: center;
+      gap: 0.75rem;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 0.95rem 1.35rem;
+      font: inherit;
+      font-weight: 700;
+      color: #fff;
+      background: linear-gradient(135deg, var(--accent), #5d7cff);
+      cursor: pointer;
+      transition: transform 0.16s ease, background 0.16s ease;
+    }
+
+    button:hover {
+      background: linear-gradient(135deg, var(--accent-strong), #4e6efc);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible,
+    input:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      font-size: 0.92rem;
+      font-weight: 600;
+      color: var(--accent-strong);
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 1.35rem;
+      }
+
+      .button-row {
+        flex-direction: column;
+        align-items: stretch;
+      }
+
+      button {
+        width: 100%;
+      }
+    }
+
+    @media (forced-colors: active) {
+      body {
+        background: Canvas;
+        color: CanvasText;
+      }
+
+      .card,
+      .form-field {
+        background: Canvas;
+        border-color: ButtonBorder;
+        box-shadow: none;
+      }
+
+      .eyebrow,
+      .helper-text,
+      .intro,
+      .status {
+        color: CanvasText;
+      }
+
+      .skip-link,
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+        border: 1px solid ButtonBorder;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <div id="root"></div>
+  <script>
+    const ConsentField = () => `
+      <div class="form-field">
+        <div class="checkbox-row">
+          <input
+            id="termsConsent"
+            name="termsConsent"
+            type="checkbox"
+            required
+            aria-describedby="termsHelper"
+          />
+          <label for="termsConsent">I agree to the terms of use.</label>
+        </div>
+        <p id="termsHelper" class="helper-text">
+          Required to continue with your submission.
+        </p>
+      </div>
+    `;
+
+    const SubmitButton = () => `
+      <div class="button-row">
+        <button type="submit">Submit</button>
+      </div>
+    `;
+
+    const App = () => `
+      <div class="page-shell">
+        <main id="main-content" class="card">
+          <p class="eyebrow">Account setup</p>
+          <h1>Confirm your consent</h1>
+          <p class="intro">
+            Review the final step below and confirm that you agree before submitting.
+          </p>
+          <form id="consentForm" novalidate>
+            ${ConsentField()}
+            ${SubmitButton()}
+            <p id="formStatus" class="status" aria-live="polite"></p>
+          </form>
+        </main>
+      </div>
+    `;
+
+    const root = document.getElementById("root");
+    root.innerHTML = App();
+
+    const form = document.getElementById("consentForm");
+    const checkbox = document.getElementById("termsConsent");
